mapper.insert:
/* saleson.shop.designateddonation.DesignatedDonationMapper.insertDesignatedDonationInfo 지정기부 프로젝트 등록 */
INSERT INTO G_DSGN_DNTN_BIZ_MNG
	(
		DSGN_DNTN_BIZ_TTL
		, DSGN_DNTN_BIZ_CN
		, DSGN_DNTN_BIZ_BGNG_YMD
		, DSGN_DNTN_BIZ_END_YMD
		, GOAL_AMT
		, DSGN_DNTN_BIZ_STTS_CD
		, RLS_YN
		, DSGN_DNTN_BIZ_SE_CD
		, DSGN_DNTN_BIZ_SE_DTL_CD
		, LCLGV_CD
		, DSGN_DNTN_BIZ_ETC_CN
		, FRST_RGTR_ID
		, LAST_RGTR_ID
		, LAST_REG_DT
		, DSGN_DNTN_BIZ_DEPT_ID
	)
	VALUE
	(
		#{prjSubject}
		, #{prjCn}
		, #{prjStDt}
		, #{prjEdDt}
		, #{targetAmt}
		, #{prjStatus}
		, #{displayFlag}
		, #{bsnsType}
		, #{bsnsSubType}
		, #{locgovCode}
		, #{contentEtc}
		, #{frstRegisterId}
		, #{frstRegisterId}
		, 
		, #{dsgncntrPartId}
	)

mapper.update:
/* saleson.shop.designateddonation.DesignatedDonationMapper.updateDesignatedDonationInfo 지정기부 프로젝트 수정 */
UPDATE G_DSGN_DNTN_BIZ_MNG
	SET 
		LAST_RGTR_ID = #{lastUpdusrId}
		, LAST_REG_DT = #{lastUpdtPnttm}

		, DSGN_DNTN_BIZ_TTL = #{prjSubject}


		, DSGN_DNTN_BIZ_CN = #{prjCn}


		, DSGN_DNTN_BIZ_BGNG_YMD = #{prjStDt}


		, DSGN_DNTN_BIZ_END_YMD = #{prjEdDt}


		, GOAL_AMT = #{targetAmt}


		, DSGN_DNTN_BIZ_STTS_CD = #{prjStatus}


		, RLS_YN = #{displayFlag}


		, DSGN_DNTN_BIZ_SE_CD = #{bsnsType}


		, DSGN_DNTN_BIZ_SE_DTL_CD = #{bsnsSubType}


		, DSGN_DNTN_BIZ_RPRS_IMG = #{prjImage}


		, DSGN_DNTN_BIZ_ETC_CN = #{contentEtc}

		, DSGN_DNTN_BIZ_DEPT_ID = #{dsgncntrPartId}
WHERE 1=1
	AND DSGN_DNTN_BIZ_ID = #{prjId}

mapper.select:
/* saleson.shop.designateddonation.DesignatedDonationMapper.selectDesignatedDonationListCount 지정기부 목록 카운트 조회 */ SELECT COUNT(*) FROM ( SELECT T_A.PRJ_ID , CASE WHEN T_A.PRJ_STATUS = '2' THEN CASE WHEN T_B.CNTR_AMT > T_A.TARGET_AMT THEN '9' WHEN IN_DATE = 3 THEN '9' ELSE T_A.PRJ_STATUS END ELSE T_A.PRJ_STATUS END AS PRJ_STATUS , T_A.BSNS_TYPE , T_A.BSNS_SUB_TYPE , T_A.PRJ_SUBJECT , T_A.PRJ_ST_DT , T_A.PRJ_ED_DT , T_A.TARGET_AMT , T_A.DISPLAY_FLAG , T_A.FRST_REGIST_PNTTM , T_A.IN_DATE FROM ( SELECT P.DSGN_DNTN_BIZ_ID AS PRJ_ID , MAX(P.DSGN_DNTN_BIZ_STTS_CD) AS PRJ_STATUS , MAX(P.DSGN_DNTN_BIZ_SE_CD) AS BSNS_TYPE , MAX(P.DSGN_DNTN_BIZ_SE_DTL_CD) AS BSNS_SUB_TYPE , MAX(P.DSGN_DNTN_BIZ_TTL) AS PRJ_SUBJECT , MAX(P.DSGN_DNTN_BIZ_BGNG_YMD) AS PRJ_ST_DT , MAX(P.DSGN_DNTN_BIZ_END_YMD) AS PRJ_ED_DT , MAX(P.GOAL_AMT) AS TARGET_AMT , MAX(P.RLS_YN) AS DISPLAY_FLAG , MAX(P.FRST_REG_DT) AS FRST_REGIST_PNTTM , CASE WHEN DSGN_DNTN_BIZ_END_YMD >= DATE_FORMAT(NOW(), '%Y%m%d') THEN CASE WHEN DSGN_DNTN_BIZ_BGNG_YMD <= DATE_FORMAT(NOW(), '%Y%m%d') THEN 1 ELSE 2 END ELSE 3 END AS IN_DATE FROM G_DSGN_DNTN_BIZ_MNG P JOIN OP_COMMON_CODE C1 ON C1.CODE_TYPE = 'BUSINESS_TYPE' AND C1.ID = P.DSGN_DNTN_BIZ_SE_CD JOIN G_LOCGOV G ON G.LOCGOV_CODE = P.LCLGV_CD LEFT OUTER JOIN G_DSGN_DNTN_BIZ_DEPT_MNG DPM ON DPM.DSGN_DNTN_BIZ_DEPT_ID = P.DSGN_DNTN_BIZ_DEPT_ID WHERE 1 = 1
AND P.LCLGV_CD = #{locgovCode}
AND P.LCLGV_CD IN (SELECT LOCGOV_CODE FROM G_LOCGOV WHERE UPPER_LOCGOV_CODE = #{upperLocgovCode})
AND P.DSGN_DNTN_BIZ_SE_CD = #{bsnsType}
AND ((P.DSGN_DNTN_BIZ_BGNG_YMD BETWEEN #{prjStDt} AND #{prjEdDt}) OR (P.DSGN_DNTN_BIZ_END_YMD BETWEEN #{prjStDt} AND #{prjEdDt}) OR (#{prjStDt} BETWEEN P.DSGN_DNTN_BIZ_BGNG_YMD AND P.DSGN_DNTN_BIZ_END_YMD) OR (#{prjEdDt} BETWEEN P.DSGN_DNTN_BIZ_BGNG_YMD AND P.DSGN_DNTN_BIZ_END_YMD) )
AND (#{prjStDt} BETWEEN P.DSGN_DNTN_BIZ_BGNG_YMD AND P.DSGN_DNTN_BIZ_END_YMD)
AND (#{prjEdDt} BETWEEN P.DSGN_DNTN_BIZ_BGNG_YMD AND P.DSGN_DNTN_BIZ_END_YMD)
AND P.DSGN_DNTN_BIZ_ID NOT IN (
#{item}
)
AND DPM.DSGN_DNTN_BIZ_DEPT_ID = #{dsgncntrPartId}
AND P.RLS_YN = #{displayFlag}
AND P.DSGN_DNTN_BIZ_TTL LIKE CONCAT('%', #{searchKeyword}, '%')
GROUP BY P.DSGN_DNTN_BIZ_ID ) T_A LEFT JOIN ( SELECT C.DSGN_DNTN_BIZ_ID AS PRJ_ID , NVL(SUM(C.CNTR_AMT), 0) AS CNTR_AMT FROM G_CNTR C WHERE 1=1 AND C.DSGN_DNTN_BIZ_ID > 0 AND C.CNTR_DE <= TO_CHAR(SYSDATE , 'YYYYMMDD') AND C.DELETE_AT = 'N' AND C.STTEMNT_PAY_DE IS NOT NULL AND C.CNTR_STTUS_CODE = '200' GROUP BY C.DSGN_DNTN_BIZ_ID ) T_B ON T_A.PRJ_ID = T_B.PRJ_ID WHERE 1=1 GROUP BY T_A.PRJ_ID ) T_C WHERE 1=1
AND T_C.PRJ_STATUS = #{prjStatus}
AND T_C.PRJ_STATUS = '2' AND SYS_DATE BETWEEN T_C.PRJ_ST_DT AND T_C.PRJ_ED_DT
AND T_C.PRJ_STATUS IN ('2', '9') AND T_C.DISPLAY_FLAG = 'Y'

/* saleson.shop.designateddonation.DesignatedDonationMapper.selectImgDescListByPrjId 지정기부 이미지 접근성 설명 조회 */
SELECT IMG_EXPLN AS PRJSVALUES
   ,IMG_SEQ AS PRJSINDEXES
FROM G_DSGN_DNTN_BIZ_CN_IMG_EXPLN
WHERE DSGN_DNTN_BIZ_ID = #{value}
ORDER BY IMG_SEQ ASC;

mapper.delete:
/* saleson.shop.designateddonation.DesignatedDonationMapper.deleteImgDescList 지정기부 이미지 접근성 설명 삭제 */
DELETE G_DSGN_DNTN_BIZ_CN_IMG_EXPLN
WHERE DSGN_DNTN_BIZ_ID = #{value}

mapper.insert:
/* saleson.shop.designateddonation.DesignatedDonationMapper.insertImgDescList 지정기부 이미지 접근성 설명 등록 */
INSERT INTO G_DSGN_DNTN_BIZ_CN_IMG_EXPLN
	(
		DSGN_DNTN_BIZ_ID
		, IMG_EXPLN
		, IMG_SEQ
		, FRST_RGTR_ID
	)
	VALUES

	(
		#{prjId}
		, #{prjImageExplain.prjsValues}
		, #{prjImageExplain.prjsIndexes}
		, #{frstRegisterId}
	)

mapper.select:
/* saleson.shop.designateddonation.DesignatedDonationMapper.getMaxOrderingOfPrjImageByPrjId 지정기부 이미지 설명 순서 최대 값 조회 */
SELECT IFNULL(MAX(IMG_SEQ), 0) + 1
FROM G_DSGN_DNTN_BIZ_IMG_MNG
WHERE DSGN_DNTN_BIZ_ID = #{value}

mapper.insert:
/* saleson.shop.designateddonation.DesignatedDonationMapper.insertPrjImage 지정기부 이미지 등록 */

INSERT INTO G_DSGN_DNTN_BIZ_IMG_MNG (DSGN_DNTN_BIZ_ID, IMG_NM, IMG_SEQ, FRST_RGTR_ID)
VALUES (#{prjId}, #{imageName}, #{ordering}, #{frstRegisterId})

mapper.delete:
/* deleteImg 지정기부 이미지 삭제 by prjId */
DELETE G_DSGN_DNTN_BIZ_IMG_MNG
WHERE DSGN_DNTN_BIZ_ID = #{value}

/* deleteImgByImageId 지정기부 이미지 삭제 by ImageId */
DELETE G_DSGN_DNTN_BIZ_IMG_MNG
WHERE DSGN_DNTN_BIZ_IMG_ID = #{value}

mapper.update:
UPDATE G_DSGN_DNTN_BIZ_MNG SET
	DSGN_DNTN_BIZ_RPRS_IMG = #{prjImage}
WHERE
	DSGN_DNTN_BIZ_ID = #{prjId}

mapper.select:
/* saleson.shop.designateddonation.DesignatedDonationMapper.selectDesignatedDonationDetail 지정기부 상세 조회 */ SELECT T_A.PRJ_ID , T_A.PRJ_SUBJECT , T_A.PRJ_CN , T_A.PRJ_ST_DT , T_A.PRJ_ED_DT , T_A.TARGET_AMT
, T_A.DISPLAY_FLAG , T_A.PRJ_IMAGE , T_A.BSNS_TYPE , T_A.BSNS_SUB_TYPE , T_A.LOCGOV_CODE , T_A.UPPER_LOCGOV_CODE , T_A.FRST_REGIST_PNTTM , T_A.LOCGOV_NM , T_A.CNTR_CNT , T_A.SUM_AMT , T_A.RATE_AMT , T_A.POINT_RATE , T_A.IN_DATE , T_A.LEFT_DAY , CASE WHEN T_A.PRJ_STATUS = '2' THEN CASE WHEN T_A.CNTR_AMT > T_A.TARGET_AMT THEN '9' WHEN IN_DATE = 3 THEN '9' ELSE T_A.PRJ_STATUS END ELSE T_A.PRJ_STATUS END AS PRJ_STATUS
, T_A.CONTENT_ETC
, T_A.DSGNCNTR_PART_ID , T_A.DSGNCNTR_PART_NAME FROM ( SELECT DPM.DSGN_DNTN_BIZ_ID AS PRJ_ID , DPM.DSGN_DNTN_BIZ_TTL AS PRJ_SUBJECT , DPM.DSGN_DNTN_BIZ_CN AS PRJ_CN , DPM.DSGN_DNTN_BIZ_BGNG_YMD AS PRJ_ST_DT , DPM.DSGN_DNTN_BIZ_END_YMD AS PRJ_ED_DT , DPM.GOAL_AMT AS TARGET_AMT , DPM.DSGN_DNTN_BIZ_STTS_CD AS PRJ_STATUS , DPM.RLS_YN AS DISPLAY_FLAG , DPM.DSGN_DNTN_BIZ_RPRS_IMG AS PRJ_IMAGE , DPM.DSGN_DNTN_BIZ_SE_CD AS BSNS_TYPE , DPM.DSGN_DNTN_BIZ_SE_DTL_CD AS BSNS_SUB_TYPE , LOC.UPPER_LOCGOV_CODE , DPM.LCLGV_CD AS LOCGOV_CODE , DPM.FRST_REG_DT AS FRST_REGIST_PNTTM , CONCAT(LOC.UPPER_LOCGOV_NM , ' ', LOC.LOCGOV_NM) AS LOCGOV_NM , CASE WHEN DSGN_DNTN_BIZ_END_YMD >= DATE_FORMAT(NOW(), '%Y%m%d') THEN CASE WHEN DSGN_DNTN_BIZ_BGNG_YMD <= DATE_FORMAT(NOW(), '%Y%m%d') THEN 1 ELSE 2 END ELSE 3 END AS IN_DATE , DATEDIFF(NOW(), DSGN_DNTN_BIZ_END_YMD) AS LEFT_DAY , CS.POINT_RATE , CNTR.CNTR_CNT AS CNTR_CNT , CNTR.CNTR_AMT AS CNTR_AMT , CNTR.SUM_AMT AS SUM_AMT , FLOOR(CNTR.CNTR_AMT * 10000.0 / GOAL_AMT) / 100 AS RATE_AMT
, DPM.DSGN_DNTN_BIZ_ETC_CN AS CONTENT_ETC
, PART.DSGN_DNTN_BIZ_DEPT_ID AS DSGNCNTR_PART_ID , IFNULL(PART.DSGN_DNTN_BIZ_DEPT_NM, '부서 미지정') AS DSGNCNTR_PART_NAME FROM G_DSGN_DNTN_BIZ_MNG DPM LEFT OUTER JOIN ( SELECT DSGN_DNTN_BIZ_ID , IFNULL(COUNT(CNTR_SN), 0) AS CNTR_CNT , IFNULL(SUM(IFNULL(CNTR_AMT, 0)), 0) AS CNTR_AMT , IFNULL(SUM(CAST(CNTR_AMT AS BIGINT)), 0) AS SUM_AMT FROM G_CNTR WHERE DELETE_AT = 'N' AND STTEMNT_PAY_DE IS NOT NULL AND CNTR_STTUS_CODE = '200' AND DSGN_DNTN_BIZ_ID = #{prjId} GROUP BY DSGN_DNTN_BIZ_ID ) CNTR ON CNTR.DSGN_DNTN_BIZ_ID = DPM.DSGN_DNTN_BIZ_ID LEFT OUTER JOIN G_LOCGOV LOC ON LOC.LOCGOV_CODE = DPM.LCLGV_CD LEFT OUTER JOIN G_CTBNY_SETUP CS ON CS.LOCGOV_CODE = LOC.LOCGOV_CODE LEFT OUTER JOIN G_DSGN_DNTN_BIZ_DEPT_MNG PART ON DPM.DSGN_DNTN_BIZ_DEPT_ID = PART.DSGN_DNTN_BIZ_DEPT_ID WHERE 1=1 AND DPM.DSGN_DNTN_BIZ_ID = #{prjId}
AND DPM.DSGN_DNTN_BIZ_STTS_CD IN ('2', '9') AND DPM.RLS_YN = 'Y'
AND DPM.LCLGV_CD = #{locgovCode}
AND DATE_FORMAT(NOW(), '%Y%m%d') BETWEEN DPM.DSGN_DNTN_BIZ_BGNG_YMD AND DPM.DSGN_DNTN_BIZ_END_YMD
GROUP BY DPM.DSGN_DNTN_BIZ_ID ) T_A

/* saleson.shop.designateddonation.DesignatedDonationMapper.selectDesignatedCntrList 지정기부 기부목록 조회 */ SELECT PRJ_ID , CNTR_DE , CNTR_AMT , ENC_LOGIN_ID AS LOGIN_ID , ENC_USER_NAME AS USER_NAME , GIVE_ORDER , CHEER_MSG , CNTR_SN FROM (
SELECT * FROM ( SELECT CNTR.CNTR_DE , CNTR.CNTR_AMT , U.LOGIN_ID AS ENC_LOGIN_ID , U.USER_NAME AS ENC_USER_NAME , CNTR.DSGN_DNTN_BIZ_ID AS PRJ_ID , CNTR.FRST_REGIST_PNTTM , CASE WHEN CNTR.USER_ID = #{userId} THEN 1 ELSE 0 END AS GIVE_ORDER , CM.USER_MSG AS CHEER_MSG , CNTR.CNTR_SN FROM G_CNTR CNTR LEFT OUTER JOIN G_DSGN_DNTN_BIZ_USER_MSG CM ON CNTR.CNTR_SN = CM.DNTN_SN , OP_USER U WHERE CNTR.DELETE_AT = 'N' AND CNTR.STTEMNT_PAY_DE IS NOT NULL AND CNTR.CNTR_STTUS_CODE = '200' AND CNTR.DSGN_DNTN_BIZ_ID = #{prjId} AND U.USER_ID = CNTR.USER_ID ) ORDER BY GIVE_ORDER DESC, FRST_REGIST_PNTTM DESC
)

/* saleson.shop.designateddonation.DesignatedDonationMapper.selectDesignatedLocgovStat 지정기부 지자체별 통계 집계 */ SELECT NVL(SUM(TARGET_AMT), 0) AS TOT_TARGET_AMT , NVL(SUM(CNTR_AMT) , 0) AS TOT_CNTR_AMT , CASE WHEN NVL(SUM(TARGET_AMT),0) <> 0 THEN FLOOR(SUM(CNTR_AMT) * 10000.0 / SUM(TARGET_AMT)) / 100 ELSE 0 END AS TOT_ACHV_RT , NVL(SUM(CNTR_CNT) , 0) AS TOT_CNTR_CNT FROM ( SELECT TARGET_AMT , CNTR_AMT , CNTR_CNT , PRJ_ID , LOCGOV_CODE , BSNS_TYPE , PRJ_ST_DT , PRJ_ED_DT , CASE WHEN PRJ_STATUS = '2' THEN CASE WHEN CNTR_AMT > TARGET_AMT THEN '9' WHEN IN_DATE = 3 THEN '9' ELSE PRJ_STATUS END ELSE PRJ_STATUS END AS PRJ_STATUS FROM ( SELECT MAX(P.GOAL_AMT) AS TARGET_AMT , IFNULL(C.CNTR_AMT, 0) AS CNTR_AMT , IFNULL(C.CNT, 0) AS CNTR_CNT , P.DSGN_DNTN_BIZ_ID AS PRJ_ID , P.LCLGV_CD AS LOCGOV_CODE , P.DSGN_DNTN_BIZ_SE_CD AS BSNS_TYPE , P.DSGN_DNTN_BIZ_BGNG_YMD AS PRJ_ST_DT , P.DSGN_DNTN_BIZ_END_YMD AS PRJ_ED_DT , P.DSGN_DNTN_BIZ_STTS_CD AS PRJ_STATUS , CASE WHEN DSGN_DNTN_BIZ_END_YMD >= DATE_FORMAT(NOW(), '%Y%m%d') THEN CASE WHEN DSGN_DNTN_BIZ_BGNG_YMD <= DATE_FORMAT(NOW(), '%Y%m%d') THEN 1 ELSE 2 END ELSE 3 END AS IN_DATE FROM G_DSGN_DNTN_BIZ_MNG P
JOIN G_DSGN_DNTN_BIZ_DEPT_MNGR_MPNG DPUM ON P.DSGN_DNTN_BIZ_DEPT_ID = DPUM.DSGN_DNTN_BIZ_DEPT_ID AND DPUM.USER_ID = #{userId}
LEFT OUTER JOIN ( SELECT SUM(CAST(CNTR_AMT AS BIGINT)) AS CNTR_AMT , COUNT(*) AS CNT , DSGN_DNTN_BIZ_ID FROM G_CNTR WHERE 1=1 AND CNTR_DE <= TO_CHAR(SYSDATE , 'YYYYMMDD') AND DELETE_AT = 'N' AND STTEMNT_PAY_DE IS NOT NULL AND CNTR_STTUS_CODE = '200' AND DSGN_DNTN_BIZ_ID > 0 GROUP BY DSGN_DNTN_BIZ_ID ) C ON P.DSGN_DNTN_BIZ_ID = C.DSGN_DNTN_BIZ_ID WHERE 1=1
AND P.LCLGV_CD = #{shLocgovCode}
AND P.LCLGV_CD IN ( SELECT LOCGOV.LOCGOV_CODE FROM G_LOCGOV LOCGOV WHERE LOCGOV.UPPER_LOCGOV_CODE = #{shWdr} )
AND ((#{bsnsType} = '0') OR (#{bsnsType} <> '0' AND P.DSGN_DNTN_BIZ_SE_CD = #{bsnsType})) AND ((P.DSGN_DNTN_BIZ_BGNG_YMD BETWEEN #{frDt} AND #{toDt}) OR (P.DSGN_DNTN_BIZ_END_YMD BETWEEN #{frDt} AND #{toDt}) OR (#{frDt} BETWEEN P.DSGN_DNTN_BIZ_BGNG_YMD AND P.DSGN_DNTN_BIZ_END_YMD) OR (#{toDt} BETWEEN P.DSGN_DNTN_BIZ_BGNG_YMD AND P.DSGN_DNTN_BIZ_END_YMD) )
AND P.RLS_YN = #{displayFlag}
AND P.DSGN_DNTN_BIZ_TTL LIKE CONCAT('%', #{searchKeyword}, '%')
GROUP BY P.DSGN_DNTN_BIZ_ID ) T_A ) T_B WHERE 1 = 1 AND ((#{prjStatus} = '0') OR (#{prjStatus} <> '0' AND T_B.PRJ_STATUS = #{prjStatus}))

/* saleson.shop.designateddonation.DesignatedDonationMapper.selectDesignatedLocgovCntrStat 지정기부 지자체별 기부 집계 */
SELECT T_B.LOCGOV_CODE , CONCAT(MAX(G.UPPER_LOCGOV_NM), ' ', MAX(G.LOCGOV_NM)) AS LOCGOV_NM , SUM(CAST(PRJ_CNT AS BIGINT)) AS PRJ_CNT , SUM(CAST(STATU_2_CNT AS BIGINT)) AS STATU_2_CNT , SUM(CAST(STATU_9_CNT AS BIGINT)) AS STATU_9_CNT , SUM(CAST(STATU_1_CNT AS BIGINT)) AS STATU_1_CNT , SUM(CAST(BSNS_TYPE_100_CNT AS BIGINT)) AS BSNS_TYPE_100_CNT , SUM(CAST(BSNS_TYPE_200_CNT AS BIGINT)) AS BSNS_TYPE_200_CNT , SUM(CAST(BSNS_TYPE_300_CNT AS BIGINT)) AS BSNS_TYPE_300_CNT , SUM(CAST(BSNS_TYPE_400_CNT AS BIGINT)) AS BSNS_TYPE_400_CNT , SUM(TARGET_AMT) AS TARGET_AMT , SUM(CNTR_AMT) AS CNTR_AMT
, CASE WHEN SUM(TARGET_AMT) <> 0 THEN FLOOR(SUM(IFNULL(CNTR_AMT, 0)) * 10000.0 / SUM(TARGET_AMT)) / 100 ELSE 0 END AS ACHV_RT , SUM(CAST(CNTR_CNT AS BIGINT)) AS TOT_CNTR_CNT FROM ( SELECT T_A.PRJ_ID , T_A.LOCGOV_CODE , 1 AS PRJ_CNT , CASE WHEN T_A.PRJ_STATUS = '1' THEN 1 ELSE 0 END STATU_1_CNT , CASE WHEN T_A.PRJ_STATUS = '2' THEN 1 ELSE 0 END STATU_2_CNT , CASE WHEN T_A.PRJ_STATUS = '9' THEN 1 ELSE 0 END STATU_9_CNT , CASE WHEN T_A.BSNS_TYPE = '100' THEN 1 ELSE 0 END BSNS_TYPE_100_CNT , CASE WHEN T_A.BSNS_TYPE = '200' THEN 1 ELSE 0 END BSNS_TYPE_200_CNT , CASE WHEN T_A.BSNS_TYPE = '300' THEN 1 ELSE 0 END BSNS_TYPE_300_CNT , CASE WHEN T_A.BSNS_TYPE = '400' THEN 1 ELSE 0 END BSNS_TYPE_400_CNT , T_A.TARGET_AMT , T_A.CNTR_AMT , T_A.CNTR_CNT FROM ( SELECT TARGET_AMT , CNTR_AMT , CNTR_CNT , PRJ_ID , LOCGOV_CODE , BSNS_TYPE , PRJ_ST_DT , PRJ_ED_DT , CASE WHEN PRJ_STATUS = '2' THEN CASE WHEN CNTR_AMT > TARGET_AMT THEN '9' WHEN IN_DATE = 3 THEN '9' ELSE PRJ_STATUS END ELSE PRJ_STATUS END AS PRJ_STATUS FROM ( SELECT MAX(P.GOAL_AMT) AS TARGET_AMT , IFNULL(C.CNTR_AMT, 0) AS CNTR_AMT , IFNULL(C.CNT, 0) AS CNTR_CNT , P.DSGN_DNTN_BIZ_ID AS PRJ_ID , P.LCLGV_CD AS LOCGOV_CODE , P.DSGN_DNTN_BIZ_SE_CD AS BSNS_TYPE , P.DSGN_DNTN_BIZ_BGNG_YMD AS PRJ_ST_DT , P.DSGN_DNTN_BIZ_END_YMD AS PRJ_ED_DT , P.DSGN_DNTN_BIZ_STTS_CD AS PRJ_STATUS , CASE WHEN DSGN_DNTN_BIZ_END_YMD >= DATE_FORMAT(NOW(), '%Y%m%d') THEN CASE WHEN DSGN_DNTN_BIZ_BGNG_YMD <= DATE_FORMAT(NOW(), '%Y%m%d') THEN 1 ELSE 2 END ELSE 3 END AS IN_DATE FROM G_DSGN_DNTN_BIZ_MNG P LEFT OUTER JOIN ( SELECT SUM(CAST(CNTR_AMT AS BIGINT)) AS CNTR_AMT , COUNT(*) AS CNT , DSGN_DNTN_BIZ_ID FROM G_CNTR WHERE 1=1 AND CNTR_DE <= TO_CHAR(SYSDATE , 'YYYYMMDD') AND DELETE_AT = 'N' AND STTEMNT_PAY_DE IS NOT NULL AND CNTR_STTUS_CODE = '200' AND DSGN_DNTN_BIZ_ID > 0 GROUP BY DSGN_DNTN_BIZ_ID ) C ON P.DSGN_DNTN_BIZ_ID = C.DSGN_DNTN_BIZ_ID WHERE 1=1
AND P.DSGN_DNTN_BIZ_DEPT_ID = #{dsgncntrPartId}
AND P.LCLGV_CD = #{shLocgovCode}
AND P.LCLGV_CD IN ( SELECT LOCGOV.LOCGOV_CODE FROM G_LOCGOV LOCGOV WHERE LOCGOV.UPPER_LOCGOV_CODE = #{shWdr} )
AND ((#{bsnsType} = '0') OR (#{bsnsType} <> '0' AND P.DSGN_DNTN_BIZ_SE_CD = #{bsnsType})) AND ((P.DSGN_DNTN_BIZ_BGNG_YMD BETWEEN #{frDt} AND #{toDt}) OR (P.DSGN_DNTN_BIZ_END_YMD BETWEEN #{frDt} AND #{toDt}) OR (#{frDt} BETWEEN P.DSGN_DNTN_BIZ_BGNG_YMD AND P.DSGN_DNTN_BIZ_END_YMD) OR (#{toDt} BETWEEN P.DSGN_DNTN_BIZ_BGNG_YMD AND P.DSGN_DNTN_BIZ_END_YMD) ) GROUP BY P.DSGN_DNTN_BIZ_ID ) ) T_A WHERE 1 = 1 AND ((#{prjStatus} = '0') OR (#{prjStatus} <> '0' AND T_A.PRJ_STATUS = #{prjStatus})) ) T_B , G_LOCGOV G WHERE 1=1 AND G.LOCGOV_CODE = T_B.LOCGOV_CODE GROUP BY T_B.LOCGOV_CODE

/* saleson.shop.designateddonation.DesignatedDonationMapper.selectDesignatedLocgovCntrStatCount 지정기부 지자체별 기부 집계 리스트 카운트 */ SELECT COUNT(1) FROM ( SELECT T_B.LOCGOV_CODE , CONCAT(MAX(G.UPPER_LOCGOV_NM), ' ', MAX(G.LOCGOV_NM)) AS LOCGOV_NM , SUM(CAST(PRJ_CNT AS BIGINT)) AS PRJ_CNT , SUM(CAST(STATU_2_CNT AS BIGINT)) AS STATU_2_CNT , SUM(CAST(STATU_9_CNT AS BIGINT)) AS STATU_9_CNT , SUM(CAST(STATU_1_CNT AS BIGINT)) AS STATU_1_CNT , SUM(CAST(BSNS_TYPE_100_CNT AS BIGINT)) AS BSNS_TYPE_100_CNT , SUM(CAST(BSNS_TYPE_200_CNT AS BIGINT)) AS BSNS_TYPE_200_CNT , SUM(CAST(BSNS_TYPE_300_CNT AS BIGINT)) AS BSNS_TYPE_300_CNT , SUM(CAST(BSNS_TYPE_400_CNT AS BIGINT)) AS BSNS_TYPE_400_CNT , SUM(TARGET_AMT) AS TARGET_AMT , SUM(CNTR_AMT) AS CNTR_AMT
, CASE WHEN SUM(TARGET_AMT) <> 0 THEN FLOOR(SUM(IFNULL(CNTR_AMT, 0)) * 10000.0 / SUM(TARGET_AMT)) / 100 ELSE 0 END AS ACHV_RT , SUM(CAST(CNTR_CNT AS BIGINT)) AS TOT_CNTR_CNT FROM ( SELECT T_A.PRJ_ID , T_A.LOCGOV_CODE , 1 AS PRJ_CNT , CASE WHEN T_A.PRJ_STATUS = '1' THEN 1 ELSE 0 END STATU_1_CNT , CASE WHEN T_A.PRJ_STATUS = '2' THEN 1 ELSE 0 END STATU_2_CNT , CASE WHEN T_A.PRJ_STATUS = '9' THEN 1 ELSE 0 END STATU_9_CNT , CASE WHEN T_A.BSNS_TYPE = '100' THEN 1 ELSE 0 END BSNS_TYPE_100_CNT , CASE WHEN T_A.BSNS_TYPE = '200' THEN 1 ELSE 0 END BSNS_TYPE_200_CNT , CASE WHEN T_A.BSNS_TYPE = '300' THEN 1 ELSE 0 END BSNS_TYPE_300_CNT , CASE WHEN T_A.BSNS_TYPE = '400' THEN 1 ELSE 0 END BSNS_TYPE_400_CNT , T_A.TARGET_AMT , T_A.CNTR_AMT , T_A.CNTR_CNT FROM ( SELECT TARGET_AMT , CNTR_AMT , CNTR_CNT , PRJ_ID , LOCGOV_CODE , BSNS_TYPE , PRJ_ST_DT , PRJ_ED_DT , CASE WHEN PRJ_STATUS = '2' THEN CASE WHEN CNTR_AMT > TARGET_AMT THEN '9' WHEN IN_DATE = 3 THEN '9' ELSE PRJ_STATUS END ELSE PRJ_STATUS END AS PRJ_STATUS FROM ( SELECT MAX(P.GOAL_AMT) AS TARGET_AMT , IFNULL(C.CNTR_AMT, 0) AS CNTR_AMT , IFNULL(C.CNT, 0) AS CNTR_CNT , P.DSGN_DNTN_BIZ_ID AS PRJ_ID , P.LCLGV_CD AS LOCGOV_CODE , P.DSGN_DNTN_BIZ_SE_CD AS BSNS_TYPE , P.DSGN_DNTN_BIZ_BGNG_YMD AS PRJ_ST_DT , P.DSGN_DNTN_BIZ_END_YMD AS PRJ_ED_DT , P.DSGN_DNTN_BIZ_STTS_CD AS PRJ_STATUS , CASE WHEN DSGN_DNTN_BIZ_END_YMD >= DATE_FORMAT(NOW(), '%Y%m%d') THEN CASE WHEN DSGN_DNTN_BIZ_BGNG_YMD <= DATE_FORMAT(NOW(), '%Y%m%d') THEN 1 ELSE 2 END ELSE 3 END AS IN_DATE FROM G_DSGN_DNTN_BIZ_MNG P LEFT OUTER JOIN ( SELECT SUM(CAST(CNTR_AMT AS BIGINT)) AS CNTR_AMT , COUNT(*) AS CNT , DSGN_DNTN_BIZ_ID FROM G_CNTR WHERE 1=1 AND CNTR_DE <= TO_CHAR(SYSDATE , 'YYYYMMDD') AND DELETE_AT = 'N' AND STTEMNT_PAY_DE IS NOT NULL AND CNTR_STTUS_CODE = '200' AND DSGN_DNTN_BIZ_ID > 0 GROUP BY DSGN_DNTN_BIZ_ID ) C ON P.DSGN_DNTN_BIZ_ID = C.DSGN_DNTN_BIZ_ID WHERE 1=1
AND P.LCLGV_CD = #{shLocgovCode}
AND P.LCLGV_CD IN ( SELECT LOCGOV.LOCGOV_CODE FROM G_LOCGOV LOCGOV WHERE LOCGOV.UPPER_LOCGOV_CODE = #{shWdr} )
AND ((#{bsnsType} = '0') OR (#{bsnsType} <> '0' AND P.DSGN_DNTN_BIZ_SE_CD = #{bsnsType})) AND ((P.DSGN_DNTN_BIZ_BGNG_YMD BETWEEN #{frDt} AND #{toDt}) OR (P.DSGN_DNTN_BIZ_END_YMD BETWEEN #{frDt} AND #{toDt}) OR (#{frDt} BETWEEN P.DSGN_DNTN_BIZ_BGNG_YMD AND P.DSGN_DNTN_BIZ_END_YMD) OR (#{toDt} BETWEEN P.DSGN_DNTN_BIZ_BGNG_YMD AND P.DSGN_DNTN_BIZ_END_YMD) ) GROUP BY P.DSGN_DNTN_BIZ_ID ) ) T_A WHERE 1 = 1 AND ((#{prjStatus} = '0') OR (#{prjStatus} <> '0' AND T_A.PRJ_STATUS = #{prjStatus})) ) T_B , G_LOCGOV G WHERE 1=1 AND G.LOCGOV_CODE = T_B.LOCGOV_CODE GROUP BY T_B.LOCGOV_CODE )

/* saleson.shop.designateddonation.DesignatedDonationMapper.selectDesignatedLocgovCntrDetail 지정기부 지자체별 상세내역 */ SELECT * , C2.LABEL AS PRJ_STATUS_DESC FROM ( SELECT PRJ_ID , LOCGOV_NM , CASE WHEN PRJ_STATUS = '2' THEN CASE WHEN CNTR_AMT >= TARGET_AMT THEN '9' WHEN PRJ_ED_DT < DATE_FORMAT(NOW(), '%Y%m%D') THEN '9' ELSE PRJ_STATUS END ELSE PRJ_STATUS END AS PRJ_STATUS , PRJ_IMAGE , BSNS_TYPE , BSNS_TYPE_DESC , PRJ_SUBJECT , CNTR_CNT , PRJ_ST_DT , PRJ_ED_DT , TARGET_AMT , CNTR_AMT , ACHV_RT FROM ( SELECT P.DSGN_DNTN_BIZ_ID AS PRJ_ID , CONCAT(MAX(G.UPPER_LOCGOV_NM), ' ', MAX(G.LOCGOV_NM)) AS LOCGOV_NM , MAX(P.DSGN_DNTN_BIZ_STTS_CD) AS PRJ_STATUS , MAX(P.DSGN_DNTN_BIZ_RPRS_IMG) AS PRJ_IMAGE , MAX(P.DSGN_DNTN_BIZ_SE_CD) AS BSNS_TYPE , MAX(C1.LABEL) AS BSNS_TYPE_DESC , MAX(P.DSGN_DNTN_BIZ_TTL) AS PRJ_SUBJECT , COUNT(C.*) AS CNTR_CNT , MAX(P.DSGN_DNTN_BIZ_BGNG_YMD) AS PRJ_ST_DT , MAX(P.DSGN_DNTN_BIZ_END_YMD) AS PRJ_ED_DT , MAX(P.GOAL_AMT) AS TARGET_AMT , NVL(SUM(CAST(C.CNTR_AMT AS BIGINT)), 0) AS CNTR_AMT
, CASE WHEN NVL(MAX(P.GOAL_AMT), 0) <> 0 THEN NVL(FLOOR(SUM(C.CNTR_AMT), 0) * 10000.0 / SUM(P.GOAL_AMT) / 100) ELSE 0 END AS ACHV_RT FROM OP_COMMON_CODE C1 , G_LOCGOV G , G_DSGN_DNTN_BIZ_MNG P LEFT OUTER JOIN G_CNTR C ON P.DSGN_DNTN_BIZ_ID + 0 = C.DSGN_DNTN_BIZ_ID AND C.CNTR_DE <= TO_CHAR(SYSDATE , 'YYYYMMDD') AND C.DELETE_AT = 'N' AND C.STTEMNT_PAY_DE IS NOT NULL AND C.CNTR_STTUS_CODE = '200' WHERE 1 = 1 AND C1.CODE_TYPE = 'BUSINESS_TYPE' AND C1.ID = P.DSGN_DNTN_BIZ_SE_CD AND G.LOCGOV_CODE = P.LCLGV_CD
AND P.LCLGV_CD = #{shLocgovCode}
AND P.LCLGV_CD IN ( SELECT LOCGOV.LOCGOV_CODE FROM G_LOCGOV LOCGOV WHERE LOCGOV.UPPER_LOCGOV_CODE = #{shWdr} )
AND ((#{bsnsType} = '0') OR (#{bsnsType} <> '0' AND DSGN_DNTN_BIZ_SE_CD = #{bsnsType})) AND ((DSGN_DNTN_BIZ_BGNG_YMD BETWEEN #{frDt} AND #{toDt}) OR (DSGN_DNTN_BIZ_END_YMD BETWEEN #{frDt} AND #{toDt}) OR (#{frDt} BETWEEN DSGN_DNTN_BIZ_BGNG_YMD AND DSGN_DNTN_BIZ_END_YMD) OR (#{toDt} BETWEEN DSGN_DNTN_BIZ_BGNG_YMD AND DSGN_DNTN_BIZ_END_YMD) ) GROUP BY P.DSGN_DNTN_BIZ_ID ) ) T_A JOIN OP_COMMON_CODE C2 ON T_A.PRJ_STATUS = C2.ID AND C2.CODE_TYPE = 'PRJ_STATUS' WHERE 1 = 1 AND ((#{prjStatus} = '0') OR (#{prjStatus} <> '0' AND PRJ_STATUS = #{prjStatus})) GROUP BY P.PRJ_ID

/* saleson.shop.designateddonation.DesignatedDonationMapper.selectDesignatedLocgovMonthCampaign 사업별 갬페인 진행건 비율 조회 */ SELECT T_COPY.TP , CASE WHEN T_COPY.TP = 1 THEN '사업별 캠페인 진행건 비율' ELSE '캠페인 건수' END AS COLUMN_TP_DESC , CASE WHEN T_COPY.TP = 1 THEN PRJ_RT_100 ELSE PRJ_CNT_100 END AS PRJ_BSNS_100 , CASE WHEN T_COPY.TP = 1 THEN PRJ_RT_200 ELSE PRJ_CNT_200 END AS PRJ_BSNS_200 , CASE WHEN T_COPY.TP = 1 THEN PRJ_RT_300 ELSE PRJ_CNT_300 END AS PRJ_BSNS_300 , CASE WHEN T_COPY.TP = 1 THEN PRJ_RT_400 ELSE PRJ_CNT_400 END AS PRJ_BSNS_400 , CASE WHEN T_COPY.TP = 1 THEN PRJ_RT_TOT ELSE PRJ_CNT_TOT END AS PRJ_BSNS_TOT FROM ( SELECT
CASE WHEN COUNT(*) <> 0 THEN FLOOR(SUM(CASE WHEN P.BSNS_TYPE = '100' THEN 1 ELSE 0 END) * 10000 / COUNT(*) / 100) ELSE 0 END AS PRJ_RT_100 , CASE WHEN COUNT(*) <> 0 THEN FLOOR(SUM(CASE WHEN P.BSNS_TYPE = '200' THEN 1 ELSE 0 END) * 10000 / COUNT(*) / 100) ELSE 0 END AS PRJ_RT_200 , CASE WHEN COUNT(*) <> 0 THEN FLOOR(SUM(CASE WHEN P.BSNS_TYPE = '300' THEN 1 ELSE 0 END) * 10000 / COUNT(*) / 100) ELSE 0 END AS PRJ_RT_300 , CASE WHEN COUNT(*) <> 0 THEN FLOOR(SUM(CASE WHEN P.BSNS_TYPE = '400' THEN 1 ELSE 0 END) * 10000 / COUNT(*) / 100) ELSE 0 END AS PRJ_RT_400 , CASE WHEN COUNT(*) <> 0 THEN 100 ELSE 0 end AS PRJ_RT_TOT , NVL(SUM(CASE WHEN P.BSNS_TYPE = '100' THEN 1 ELSE 0 END), 0) AS PRJ_CNT_100 , NVL(SUM(CASE WHEN P.BSNS_TYPE = '200' THEN 1 ELSE 0 END), 0) AS PRJ_CNT_200 , NVL(SUM(CASE WHEN P.BSNS_TYPE = '300' THEN 1 ELSE 0 END), 0) AS PRJ_CNT_300 , NVL(SUM(CASE WHEN P.BSNS_TYPE = '400' THEN 1 ELSE 0 END), 0) AS PRJ_CNT_400 , COUNT(*) AS PRJ_CNT_TOT FROM ( SELECT DSGN_DNTN_BIZ_SE_CD AS BSNS_TYPE , LCLGV_CD AS LOCGOV_CODE , CASE WHEN DSGN_DNTN_BIZ_STTS_CD = '2' THEN CASE WHEN SUM(C.CNTR_AMT) >= P.GOAL_AMT THEN '9' WHEN DSGN_DNTN_BIZ_END_YMD < DATE_FORMAT(NOW(), '%Y%m%D') THEN '9' ELSE DSGN_DNTN_BIZ_STTS_CD END ELSE DSGN_DNTN_BIZ_STTS_CD END AS PRJ_STATUS , DSGN_DNTN_BIZ_BGNG_YMD , DSGN_DNTN_BIZ_END_YMD FROM G_DSGN_DNTN_BIZ_MNG P LEFT OUTER JOIN ( SELECT SUM(CAST(CNTR_AMT AS BIGINT)) AS CNTR_AMT , COUNT(*) AS CNT , DSGN_DNTN_BIZ_ID FROM G_CNTR WHERE 1=1 AND CNTR_DE <= TO_CHAR(SYSDATE , 'YYYYMMDD') AND DELETE_AT = 'N' AND STTEMNT_PAY_DE IS NOT NULL AND CNTR_STTUS_CODE = '200' AND DSGN_DNTN_BIZ_ID > 0 GROUP BY DSGN_DNTN_BIZ_ID ) C ON P.DSGN_DNTN_BIZ_ID = C.DSGN_DNTN_BIZ_ID WHERE 1=1
AND P.DSGN_DNTN_BIZ_DEPT_ID = #{dsgncntrPartId}
AND P.LCLGV_CD = #{shLocgovCode}
AND P.LCLGV_CD IN ( SELECT LOCGOV.LOCGOV_CODE FROM G_LOCGOV LOCGOV WHERE LOCGOV.UPPER_LOCGOV_CODE = #{shWdr} )
AND ((P.DSGN_DNTN_BIZ_BGNG_YMD BETWEEN CONCAT(#{selYear}, '0101') AND CONCAT(#{selYear}, '1231')) OR (P.DSGN_DNTN_BIZ_END_YMD BETWEEN CONCAT(#{selYear}, '0101') AND CONCAT(#{selYear}, '1231')) OR (CONCAT(#{selYear}, '0101') BETWEEN P.DSGN_DNTN_BIZ_BGNG_YMD AND P.DSGN_DNTN_BIZ_END_YMD) OR (CONCAT(#{selYear}, '1231') BETWEEN P.DSGN_DNTN_BIZ_BGNG_YMD AND P.DSGN_DNTN_BIZ_END_YMD) ) GROUP BY P.DSGN_DNTN_BIZ_ID ) P WHERE 1 = 1 AND ((#{prjStatus} = '0' ) OR (#{prjStatus} <> '0' AND P.PRJ_STATUS = #{prjStatus})) ) T_A , (SELECT 1 TP UNION ALL SELECT 2 TP ) T_COPY ORDER BY T_COPY.TP

/* saleson.shop.designateddonation.DesignatedDonationMapper.selectDesignatedLocgovMonthAmountRaised 모금액 비율 조회 */ SELECT T_COPY.TP , CASE WHEN T_COPY.TP = 1 THEN '모금액 비율' WHEN T_COPY.TP = 2 THEN '모금액' ELSE '목표모금액' END AS COLUMN_TP_DESC , CASE WHEN T_COPY.TP = 1 THEN CNTR_AMT_RT_100 WHEN T_COPY.TP = 2 THEN CNTR_AMT_100 ELSE TARGET_AMT_100 END AS PRJ_BSNS_100 , CASE WHEN T_COPY.TP = 1 THEN CNTR_AMT_RT_200 WHEN T_COPY.TP = 2 THEN CNTR_AMT_200 ELSE TARGET_AMT_200 END AS PRJ_BSNS_200 , CASE WHEN T_COPY.TP = 1 THEN CNTR_AMT_RT_300 WHEN T_COPY.TP = 2 THEN CNTR_AMT_300 ELSE TARGET_AMT_300 END AS PRJ_BSNS_300 , CASE WHEN T_COPY.TP = 1 THEN CNTR_AMT_RT_400 WHEN T_COPY.TP = 2 THEN CNTR_AMT_400 ELSE TARGET_AMT_400 END AS PRJ_BSNS_400 , CASE WHEN T_COPY.TP = 1 THEN CNTR_AMT_RT_TOT WHEN T_COPY.TP = 2 THEN CNTR_AMT_TOT ELSE TARGET_AMT_TOT END AS PRJ_BSNS_TOT FROM ( SELECT
CASE WHEN SUM(CNTR_AMT) <> 0 THEN FLOOR(SUM(CNTR_AMT_100) * 10000 / SUM(CNTR_AMT) / 100) ELSE 0 END AS CNTR_AMT_RT_100 , CASE WHEN SUM(CNTR_AMT) <> 0 THEN FLOOR(SUM(CNTR_AMT_200) * 10000 / SUM(CNTR_AMT) / 100) ELSE 0 END AS CNTR_AMT_RT_200 , CASE WHEN SUM(CNTR_AMT) <> 0 THEN FLOOR(SUM(CNTR_AMT_300) * 10000 / SUM(CNTR_AMT) / 100) ELSE 0 END AS CNTR_AMT_RT_300 , CASE WHEN SUM(CNTR_AMT) <> 0 THEN FLOOR(SUM(CNTR_AMT_400) * 10000 / SUM(CNTR_AMT) / 100) ELSE 0 END AS CNTR_AMT_RT_400 , CASE WHEN SUM(CNTR_AMT) <> 0 THEN 100 ELSE 0 END AS CNTR_AMT_RT_TOT , NVL(SUM(CNTR_AMT_100) , 0) AS CNTR_AMT_100 , NVL(SUM(CNTR_AMT_200) , 0) AS CNTR_AMT_200 , NVL(SUM(CNTR_AMT_300) , 0) AS CNTR_AMT_300 , NVL(SUM(CNTR_AMT_400) , 0) AS CNTR_AMT_400 , NVL(SUM(CNTR_AMT) , 0) AS CNTR_AMT_TOT , NVL(SUM(TARGET_AMT_100), 0) AS TARGET_AMT_100 , NVL(SUM(TARGET_AMT_200), 0) AS TARGET_AMT_200 , NVL(SUM(TARGET_AMT_300), 0) AS TARGET_AMT_300 , NVL(SUM(TARGET_AMT_400), 0) AS TARGET_AMT_400 , NVL(SUM(TARGET_AMT) , 0) AS TARGET_AMT_TOT FROM ( SELECT P.DSGN_DNTN_BIZ_ID AS PRJ_ID , MAX(CASE WHEN P.DSGN_DNTN_BIZ_END_YMD <= CONCAT(#{selYear}, '1231') AND P.DSGN_DNTN_BIZ_SE_CD = '100' THEN P.GOAL_AMT ELSE 0 END) AS TARGET_AMT_100 , MAX(CASE WHEN P.DSGN_DNTN_BIZ_END_YMD <= CONCAT(#{selYear}, '1231') AND P.DSGN_DNTN_BIZ_SE_CD = '200' THEN P.GOAL_AMT ELSE 0 END) AS TARGET_AMT_200 , MAX(CASE WHEN P.DSGN_DNTN_BIZ_END_YMD <= CONCAT(#{selYear}, '1231') AND P.DSGN_DNTN_BIZ_SE_CD = '300' THEN P.GOAL_AMT ELSE 0 END) AS TARGET_AMT_300 , MAX(CASE WHEN P.DSGN_DNTN_BIZ_END_YMD <= CONCAT(#{selYear}, '1231') AND P.DSGN_DNTN_BIZ_SE_CD = '400' THEN P.GOAL_AMT ELSE 0 END) AS TARGET_AMT_400 , MAX(CASE WHEN P.DSGN_DNTN_BIZ_END_YMD <= CONCAT(#{selYear}, '1231') THEN P.GOAL_AMT ELSE 0 END) AS TARGET_AMT , SUM(CASE WHEN P.DSGN_DNTN_BIZ_SE_CD = '100' THEN C.CNTR_AMT ELSE 0 END) AS CNTR_AMT_100 , SUM(CASE WHEN P.DSGN_DNTN_BIZ_SE_CD = '200' THEN C.CNTR_AMT ELSE 0 END) AS CNTR_AMT_200 , SUM(CASE WHEN P.DSGN_DNTN_BIZ_SE_CD = '300' THEN C.CNTR_AMT ELSE 0 END) AS CNTR_AMT_300 , SUM(CASE WHEN P.DSGN_DNTN_BIZ_SE_CD = '400' THEN C.CNTR_AMT ELSE 0 END) AS CNTR_AMT_400 , SUM(C.CNTR_AMT) AS CNTR_AMT , CASE WHEN DSGN_DNTN_BIZ_STTS_CD = '2' THEN CASE WHEN SUM(C.CNTR_AMT) >= P.GOAL_AMT THEN '9' WHEN DSGN_DNTN_BIZ_END_YMD < DATE_FORMAT(NOW(), '%Y%m%D') THEN '9' ELSE DSGN_DNTN_BIZ_STTS_CD END ELSE DSGN_DNTN_BIZ_STTS_CD END AS PRJ_STATUS FROM G_DSGN_DNTN_BIZ_MNG P LEFT OUTER JOIN ( SELECT SUM(CAST(CNTR_AMT AS BIGINT)) AS CNTR_AMT , COUNT(*) AS CNT , DSGN_DNTN_BIZ_ID FROM G_CNTR WHERE 1=1 AND CNTR_DE <= TO_CHAR(SYSDATE , 'YYYYMMDD') AND DELETE_AT = 'N' AND STTEMNT_PAY_DE IS NOT NULL AND CNTR_STTUS_CODE = '200' AND DSGN_DNTN_BIZ_ID > 0 GROUP BY DSGN_DNTN_BIZ_ID ) C ON P.DSGN_DNTN_BIZ_ID = C.DSGN_DNTN_BIZ_ID WHERE 1 = 1
AND P.DSGN_DNTN_BIZ_DEPT_ID = #{dsgncntrPartId}
AND P.LCLGV_CD = #{shLocgovCode}
AND P.LCLGV_CD IN ( SELECT LOCGOV.LOCGOV_CODE FROM G_LOCGOV LOCGOV WHERE LOCGOV.UPPER_LOCGOV_CODE = #{shWdr} )
AND ((P.DSGN_DNTN_BIZ_BGNG_YMD BETWEEN CONCAT(#{selYear}, '0101') AND CONCAT(#{selYear}, '1231')) OR (P.DSGN_DNTN_BIZ_END_YMD BETWEEN CONCAT(#{selYear}, '0101') AND CONCAT(#{selYear}, '1231')) OR (CONCAT(#{selYear}, '0101') BETWEEN P.DSGN_DNTN_BIZ_BGNG_YMD AND P.DSGN_DNTN_BIZ_END_YMD) OR (CONCAT(#{selYear}, '1231') BETWEEN P.DSGN_DNTN_BIZ_BGNG_YMD AND P.DSGN_DNTN_BIZ_END_YMD) ) GROUP BY P.DSGN_DNTN_BIZ_ID ) T_A WHERE 1=1 AND ((#{prjStatus} = '0' ) OR (#{prjStatus} <> '0' AND T_A.PRJ_STATUS = #{prjStatus})) ) T_B , (SELECT 1 TP UNION ALL SELECT 2 TP UNION ALL SELECT 3 TP ) T_COPY ORDER BY T_COPY.TP

/* saleson.shop.designateddonation.DesignatedDonationMapper.selectDesignatedLocgovMonthAmount 모금액 추이 */ SELECT T_COPY.TP , CASE WHEN T_COPY.TP = 1 THEN '목표금액(원)' WHEN T_COPY.TP = 2 THEN '모금액(원)' WHEN T_COPY.TP = 3 THEN '참여자수(명)' ELSE '사업건수(건)' END AS COLUMN_TP_DESC , CASE WHEN T_COPY.TP = 1 THEN NVL(SUM(TARGET_AMT_01 ), 0) WHEN T_COPY.TP = 2 THEN NVL(SUM(CNTR_AMT_01 ), 0) WHEN T_COPY.TP = 3 THEN NVL(SUM(CNTR_CNT_01 ), 0) ELSE NVL(SUM(PRJ_CNT_01), 0) END AS M01 , CASE WHEN T_COPY.TP = 1 THEN NVL(SUM(TARGET_AMT_02 ), 0) WHEN T_COPY.TP = 2 THEN NVL(SUM(CNTR_AMT_02 ), 0) WHEN T_COPY.TP = 3 THEN NVL(SUM(CNTR_CNT_02 ), 0) ELSE NVL(SUM(PRJ_CNT_02), 0) END AS M02 , CASE WHEN T_COPY.TP = 1 THEN NVL(SUM(TARGET_AMT_03 ), 0) WHEN T_COPY.TP = 2 THEN NVL(SUM(CNTR_AMT_03 ), 0) WHEN T_COPY.TP = 3 THEN NVL(SUM(CNTR_CNT_03 ), 0) ELSE NVL(SUM(PRJ_CNT_03), 0) END AS M03 , CASE WHEN T_COPY.TP = 1 THEN NVL(SUM(TARGET_AMT_04 ), 0) WHEN T_COPY.TP = 2 THEN NVL(SUM(CNTR_AMT_04 ), 0) WHEN T_COPY.TP = 3 THEN NVL(SUM(CNTR_CNT_04 ), 0) ELSE NVL(SUM(PRJ_CNT_04), 0) END AS M04 , CASE WHEN T_COPY.TP = 1 THEN NVL(SUM(TARGET_AMT_05 ), 0) WHEN T_COPY.TP = 2 THEN NVL(SUM(CNTR_AMT_05 ), 0) WHEN T_COPY.TP = 3 THEN NVL(SUM(CNTR_CNT_05 ), 0) ELSE NVL(SUM(PRJ_CNT_05), 0) END AS M05 , CASE WHEN T_COPY.TP = 1 THEN NVL(SUM(TARGET_AMT_06 ), 0) WHEN T_COPY.TP = 2 THEN NVL(SUM(CNTR_AMT_06 ), 0) WHEN T_COPY.TP = 3 THEN NVL(SUM(CNTR_CNT_06 ), 0) ELSE NVL(SUM(PRJ_CNT_06), 0) END AS M06 , CASE WHEN T_COPY.TP = 1 THEN NVL(SUM(TARGET_AMT_07 ), 0) WHEN T_COPY.TP = 2 THEN NVL(SUM(CNTR_AMT_07 ), 0) WHEN T_COPY.TP = 3 THEN NVL(SUM(CNTR_CNT_07 ), 0) ELSE NVL(SUM(PRJ_CNT_07), 0) END AS M07 , CASE WHEN T_COPY.TP = 1 THEN NVL(SUM(TARGET_AMT_08 ), 0) WHEN T_COPY.TP = 2 THEN NVL(SUM(CNTR_AMT_08 ), 0) WHEN T_COPY.TP = 3 THEN NVL(SUM(CNTR_CNT_08 ), 0) ELSE NVL(SUM(PRJ_CNT_08), 0) END AS M08 , CASE WHEN T_COPY.TP = 1 THEN NVL(SUM(TARGET_AMT_09 ), 0) WHEN T_COPY.TP = 2 THEN NVL(SUM(CNTR_AMT_09 ), 0) WHEN T_COPY.TP = 3 THEN NVL(SUM(CNTR_CNT_09 ), 0) ELSE NVL(SUM(PRJ_CNT_09), 0) END AS M09 , CASE WHEN T_COPY.TP = 1 THEN NVL(SUM(TARGET_AMT_10 ), 0) WHEN T_COPY.TP = 2 THEN NVL(SUM(CNTR_AMT_10 ), 0) WHEN T_COPY.TP = 3 THEN NVL(SUM(CNTR_CNT_10 ), 0) ELSE NVL(SUM(PRJ_CNT_10), 0) END AS M10 , CASE WHEN T_COPY.TP = 1 THEN NVL(SUM(TARGET_AMT_11 ), 0) WHEN T_COPY.TP = 2 THEN NVL(SUM(CNTR_AMT_11 ), 0) WHEN T_COPY.TP = 3 THEN NVL(SUM(CNTR_CNT_11 ), 0) ELSE NVL(SUM(PRJ_CNT_11), 0) END AS M11 , CASE WHEN T_COPY.TP = 1 THEN NVL(SUM(TARGET_AMT_12 ), 0) WHEN T_COPY.TP = 2 THEN NVL(SUM(CNTR_AMT_12 ), 0) WHEN T_COPY.TP = 3 THEN NVL(SUM(CNTR_CNT_12 ), 0) ELSE NVL(SUM(PRJ_CNT_12), 0) END AS M12 , CASE WHEN T_COPY.TP = 1 THEN NVL(SUM(TARGET_AMT_TOT ), 0) WHEN T_COPY.TP = 2 THEN NVL(SUM(CNTR_AMT_TOT ), 0) WHEN T_COPY.TP = 3 THEN NVL(SUM(CNTR_CNT_TOT ), 0) ELSE NVL(SUM(PRJ_CNT_01), 0) + NVL(SUM(PRJ_CNT_02), 0) + NVL(SUM(PRJ_CNT_03), 0) + NVL(SUM(PRJ_CNT_04), 0) + NVL(SUM(PRJ_CNT_05), 0) + NVL(SUM(PRJ_CNT_06), 0) + NVL(SUM(PRJ_CNT_07), 0) + NVL(SUM(PRJ_CNT_08), 0) + NVL(SUM(PRJ_CNT_09), 0) + NVL(SUM(PRJ_CNT_10), 0) + NVL(SUM(PRJ_CNT_11), 0) + NVL(SUM(PRJ_CNT_12), 0) END AS TOTAL FROM ( SELECT P.PRJ_ID , MAX(CASE WHEN P.PRJ_ED_DT <= CONCAT(#{selYear}, '1231') AND SUBSTR(P.PRJ_ED_DT, 5, 2) = '01' THEN P.TARGET_AMT ELSE 0 END) AS TARGET_AMT_01 , MAX(CASE WHEN P.PRJ_ED_DT <= CONCAT(#{selYear}, '1231') AND SUBSTR(P.PRJ_ED_DT, 5, 2) = '02' THEN P.TARGET_AMT ELSE 0 END) AS TARGET_AMT_02 , MAX(CASE WHEN P.PRJ_ED_DT <= CONCAT(#{selYear}, '1231') AND SUBSTR(P.PRJ_ED_DT, 5, 2) = '03' THEN P.TARGET_AMT ELSE 0 END) AS TARGET_AMT_03 , MAX(CASE WHEN P.PRJ_ED_DT <= CONCAT(#{selYear}, '1231') AND SUBSTR(P.PRJ_ED_DT, 5, 2) = '04' THEN P.TARGET_AMT ELSE 0 END) AS TARGET_AMT_04 , MAX(CASE WHEN P.PRJ_ED_DT <= CONCAT(#{selYear}, '1231') AND SUBSTR(P.PRJ_ED_DT, 5, 2) = '05' THEN P.TARGET_AMT ELSE 0 END) AS TARGET_AMT_05 , MAX(CASE WHEN P.PRJ_ED_DT <= CONCAT(#{selYear}, '1231') AND SUBSTR(P.PRJ_ED_DT, 5, 2) = '06' THEN P.TARGET_AMT ELSE 0 END) AS TARGET_AMT_06 , MAX(CASE WHEN P.PRJ_ED_DT <= CONCAT(#{selYear}, '1231') AND SUBSTR(P.PRJ_ED_DT, 5, 2) = '07' THEN P.TARGET_AMT ELSE 0 END) AS TARGET_AMT_07 , MAX(CASE WHEN P.PRJ_ED_DT <= CONCAT(#{selYear}, '1231') AND SUBSTR(P.PRJ_ED_DT, 5, 2) = '08' THEN P.TARGET_AMT ELSE 0 END) AS TARGET_AMT_08 , MAX(CASE WHEN P.PRJ_ED_DT <= CONCAT(#{selYear}, '1231') AND SUBSTR(P.PRJ_ED_DT, 5, 2) = '09' THEN P.TARGET_AMT ELSE 0 END) AS TARGET_AMT_09 , MAX(CASE WHEN P.PRJ_ED_DT <= CONCAT(#{selYear}, '1231') AND SUBSTR(P.PRJ_ED_DT, 5, 2) = '10' THEN P.TARGET_AMT ELSE 0 END) AS TARGET_AMT_10 , MAX(CASE WHEN P.PRJ_ED_DT <= CONCAT(#{selYear}, '1231') AND SUBSTR(P.PRJ_ED_DT, 5, 2) = '11' THEN P.TARGET_AMT ELSE 0 END) AS TARGET_AMT_11 , MAX(CASE WHEN P.PRJ_ED_DT <= CONCAT(#{selYear}, '1231') AND SUBSTR(P.PRJ_ED_DT, 5, 2) = '12' THEN P.TARGET_AMT ELSE 0 END) AS TARGET_AMT_12 , MAX(CASE WHEN P.PRJ_ED_DT <= CONCAT(#{selYear}, '1231') THEN P.TARGET_AMT ELSE 0 END) AS TARGET_AMT_TOT , SUM(CASE WHEN SUBSTR(C.CNTR_DE, 5, 2) = '01' THEN C.CNTR_AMT ELSE 0 END) AS CNTR_AMT_01 , SUM(CASE WHEN SUBSTR(C.CNTR_DE, 5, 2) = '02' THEN C.CNTR_AMT ELSE 0 END) AS CNTR_AMT_02 , SUM(CASE WHEN SUBSTR(C.CNTR_DE, 5, 2) = '03' THEN C.CNTR_AMT ELSE 0 END) AS CNTR_AMT_03 , SUM(CASE WHEN SUBSTR(C.CNTR_DE, 5, 2) = '04' THEN C.CNTR_AMT ELSE 0 END) AS CNTR_AMT_04 , SUM(CASE WHEN SUBSTR(C.CNTR_DE, 5, 2) = '05' THEN C.CNTR_AMT ELSE 0 END) AS CNTR_AMT_05 , SUM(CASE WHEN SUBSTR(C.CNTR_DE, 5, 2) = '06' THEN C.CNTR_AMT ELSE 0 END) AS CNTR_AMT_06 , SUM(CASE WHEN SUBSTR(C.CNTR_DE, 5, 2) = '07' THEN C.CNTR_AMT ELSE 0 END) AS CNTR_AMT_07 , SUM(CASE WHEN SUBSTR(C.CNTR_DE, 5, 2) = '08' THEN C.CNTR_AMT ELSE 0 END) AS CNTR_AMT_08 , SUM(CASE WHEN SUBSTR(C.CNTR_DE, 5, 2) = '09' THEN C.CNTR_AMT ELSE 0 END) AS CNTR_AMT_09 , SUM(CASE WHEN SUBSTR(C.CNTR_DE, 5, 2) = '10' THEN C.CNTR_AMT ELSE 0 END) AS CNTR_AMT_10 , SUM(CASE WHEN SUBSTR(C.CNTR_DE, 5, 2) = '11' THEN C.CNTR_AMT ELSE 0 END) AS CNTR_AMT_11 , SUM(CASE WHEN SUBSTR(C.CNTR_DE, 5, 2) = '12' THEN C.CNTR_AMT ELSE 0 END) AS CNTR_AMT_12 , SUM(C.CNTR_AMT) AS CNTR_AMT_TOT , SUM(CASE WHEN SUBSTR(C.CNTR_DE, 5, 2) = '01' THEN 1 ELSE 0 END) AS CNTR_CNT_01 , SUM(CASE WHEN SUBSTR(C.CNTR_DE, 5, 2) = '02' THEN 1 ELSE 0 END) AS CNTR_CNT_02 , SUM(CASE WHEN SUBSTR(C.CNTR_DE, 5, 2) = '03' THEN 1 ELSE 0 END) AS CNTR_CNT_03 , SUM(CASE WHEN SUBSTR(C.CNTR_DE, 5, 2) = '04' THEN 1 ELSE 0 END) AS CNTR_CNT_04 , SUM(CASE WHEN SUBSTR(C.CNTR_DE, 5, 2) = '05' THEN 1 ELSE 0 END) AS CNTR_CNT_05 , SUM(CASE WHEN SUBSTR(C.CNTR_DE, 5, 2) = '06' THEN 1 ELSE 0 END) AS CNTR_CNT_06 , SUM(CASE WHEN SUBSTR(C.CNTR_DE, 5, 2) = '07' THEN 1 ELSE 0 END) AS CNTR_CNT_07 , SUM(CASE WHEN SUBSTR(C.CNTR_DE, 5, 2) = '08' THEN 1 ELSE 0 END) AS CNTR_CNT_08 , SUM(CASE WHEN SUBSTR(C.CNTR_DE, 5, 2) = '09' THEN 1 ELSE 0 END) AS CNTR_CNT_09 , SUM(CASE WHEN SUBSTR(C.CNTR_DE, 5, 2) = '10' THEN 1 ELSE 0 END) AS CNTR_CNT_10 , SUM(CASE WHEN SUBSTR(C.CNTR_DE, 5, 2) = '11' THEN 1 ELSE 0 END) AS CNTR_CNT_11 , SUM(CASE WHEN SUBSTR(C.CNTR_DE, 5, 2) = '12' THEN 1 ELSE 0 END) AS CNTR_CNT_12 , COUNT(C.*) AS CNTR_CNT_TOT , CASE WHEN CONCAT(#{selYear}, '01') BETWEEN SUBSTR(MAX(P.PRJ_ST_DT), 1, 6) AND SUBSTR(MAX(P.PRJ_ED_DT), 1, 6) THEN 1 ELSE 0 END AS PRJ_CNT_01 , CASE WHEN CONCAT(#{selYear}, '02') BETWEEN SUBSTR(MAX(P.PRJ_ST_DT), 1, 6) AND SUBSTR(MAX(P.PRJ_ED_DT), 1, 6) THEN 1 ELSE 0 END AS PRJ_CNT_02 , CASE WHEN CONCAT(#{selYear}, '03') BETWEEN SUBSTR(MAX(P.PRJ_ST_DT), 1, 6) AND SUBSTR(MAX(P.PRJ_ED_DT), 1, 6) THEN 1 ELSE 0 END AS PRJ_CNT_03 , CASE WHEN CONCAT(#{selYear}, '04') BETWEEN SUBSTR(MAX(P.PRJ_ST_DT), 1, 6) AND SUBSTR(MAX(P.PRJ_ED_DT), 1, 6) THEN 1 ELSE 0 END AS PRJ_CNT_04 , CASE WHEN CONCAT(#{selYear}, '05') BETWEEN SUBSTR(MAX(P.PRJ_ST_DT), 1, 6) AND SUBSTR(MAX(P.PRJ_ED_DT), 1, 6) THEN 1 ELSE 0 END AS PRJ_CNT_05 , CASE WHEN CONCAT(#{selYear}, '06') BETWEEN SUBSTR(MAX(P.PRJ_ST_DT), 1, 6) AND SUBSTR(MAX(P.PRJ_ED_DT), 1, 6) THEN 1 ELSE 0 END AS PRJ_CNT_06 , CASE WHEN CONCAT(#{selYear}, '07') BETWEEN SUBSTR(MAX(P.PRJ_ST_DT), 1, 6) AND SUBSTR(MAX(P.PRJ_ED_DT), 1, 6) THEN 1 ELSE 0 END AS PRJ_CNT_07 , CASE WHEN CONCAT(#{selYear}, '08') BETWEEN SUBSTR(MAX(P.PRJ_ST_DT), 1, 6) AND SUBSTR(MAX(P.PRJ_ED_DT), 1, 6) THEN 1 ELSE 0 END AS PRJ_CNT_08 , CASE WHEN CONCAT(#{selYear}, '09') BETWEEN SUBSTR(MAX(P.PRJ_ST_DT), 1, 6) AND SUBSTR(MAX(P.PRJ_ED_DT), 1, 6) THEN 1 ELSE 0 END AS PRJ_CNT_09 , CASE WHEN CONCAT(#{selYear}, '10') BETWEEN SUBSTR(MAX(P.PRJ_ST_DT), 1, 6) AND SUBSTR(MAX(P.PRJ_ED_DT), 1, 6) THEN 1 ELSE 0 END AS PRJ_CNT_10 , CASE WHEN CONCAT(#{selYear}, '11') BETWEEN SUBSTR(MAX(P.PRJ_ST_DT), 1, 6) AND SUBSTR(MAX(P.PRJ_ED_DT), 1, 6) THEN 1 ELSE 0 END AS PRJ_CNT_11 , CASE WHEN CONCAT(#{selYear}, '12') BETWEEN SUBSTR(MAX(P.PRJ_ST_DT), 1, 6) AND SUBSTR(MAX(P.PRJ_ED_DT), 1, 6) THEN 1 ELSE 0 END AS PRJ_CNT_12 FROM ( SELECT P.DSGN_DNTN_BIZ_ID AS PRJ_ID , P.DSGN_DNTN_BIZ_SE_CD AS BSNS_TYPE , P.LCLGV_CD AS LOCGOV_CODE , CASE WHEN P.DSGN_DNTN_BIZ_STTS_CD = '2' THEN CASE WHEN SUM(C.CNTR_AMT) >= P.GOAL_AMT THEN '9' WHEN P.DSGN_DNTN_BIZ_END_YMD < DATE_FORMAT(NOW(), '%Y%m%D') THEN '9' ELSE P.DSGN_DNTN_BIZ_STTS_CD END ELSE P.DSGN_DNTN_BIZ_STTS_CD END AS PRJ_STATUS , P.DSGN_DNTN_BIZ_BGNG_YMD AS PRJ_ST_DT , P.DSGN_DNTN_BIZ_END_YMD AS PRJ_ED_DT , P.GOAL_AMT AS TARGET_AMT FROM G_DSGN_DNTN_BIZ_MNG P LEFT OUTER JOIN ( SELECT SUM(CAST(CNTR_AMT AS BIGINT)) AS CNTR_AMT , COUNT(*) AS CNT , DSGN_DNTN_BIZ_ID FROM G_CNTR WHERE 1=1 AND CNTR_DE <= TO_CHAR(SYSDATE , 'YYYYMMDD') AND DELETE_AT = 'N' AND STTEMNT_PAY_DE IS NOT NULL AND CNTR_STTUS_CODE = '200' AND DSGN_DNTN_BIZ_ID > 0 GROUP BY DSGN_DNTN_BIZ_ID ) C ON P.DSGN_DNTN_BIZ_ID = C.DSGN_DNTN_BIZ_ID WHERE 1=1
AND P.DSGN_DNTN_BIZ_DEPT_ID = #{dsgncntrPartId}
AND P.LCLGV_CD = #{shLocgovCode}
AND P.LCLGV_CD IN ( SELECT LOCGOV.LOCGOV_CODE FROM G_LOCGOV LOCGOV WHERE LOCGOV.UPPER_LOCGOV_CODE = #{shWdr} )
AND ((P.DSGN_DNTN_BIZ_BGNG_YMD BETWEEN CONCAT(#{selYear}, '0101') AND CONCAT(#{selYear}, '1231')) OR (P.DSGN_DNTN_BIZ_END_YMD BETWEEN CONCAT(#{selYear}, '0101') AND CONCAT(#{selYear}, '1231')) OR (CONCAT(#{selYear}, '0101') BETWEEN P.DSGN_DNTN_BIZ_BGNG_YMD AND P.DSGN_DNTN_BIZ_END_YMD) OR (CONCAT(#{selYear}, '1231') BETWEEN P.DSGN_DNTN_BIZ_BGNG_YMD AND P.DSGN_DNTN_BIZ_END_YMD) ) GROUP BY P.DSGN_DNTN_BIZ_ID ) P LEFT OUTER JOIN G_CNTR C ON P.PRJ_ID + 0 = C.PRJ_ID AND C.CNTR_DE BETWEEN CONCAT(#{selYear}, '0101') AND CASE WHEN CONCAT(#{selYear}, '1231') <= TO_CHAR(ADDDATE( SYSDATE , INTERVAL -1 DAY), 'YYYYMMDD') THEN CONCAT(#{selYear}, '1231') ELSE TO_CHAR(ADDDATE( SYSDATE , INTERVAL -1 DAY) , 'YYYYMMDD') END AND C.DELETE_AT = 'N' AND C.STTEMNT_PAY_DE IS NOT NULL AND C.CNTR_STTUS_CODE = '200' WHERE 1 = 1
AND ((#{prjStatus} = '0' ) OR (#{prjStatus} <> '0' AND P.PRJ_STATUS = #{prjStatus}))
GROUP BY P.PRJ_ID ) T_A , (SELECT 1 TP UNION ALL SELECT 2 TP UNION ALL SELECT 3 TP UNION ALL SELECT 4 TP ) T_COPY GROUP BY T_COPY.TP

