/* saleson.shop.designateddonation.DesignatedDonationMapper.selectCntrInfo 응원메시지 체크용 기부 정보 조회 */
SELECT
	CNTR_SN
FROM G_CNTR
WHERE 1=1
	AND CNTR_SN = #{cntrSn}
	AND STTEMNT_PAY_DE IS NOT NULL
	AND CNTR_STTUS_CODE = '200'
	AND DELETE_AT = 'N'
	AND USER_ID = #{userId}

/* saleson.shop.designateddonation.DesignatedDonationMapper.selectDesignatedDonationNoticeList 공지내역 조회 */
SELECT DPN.DSGN_DNTN_BIZ_NTC_ID AS PRJ_NOTICE_ID , DPN.DSGN_DNTN_BIZ_ID AS PRJ_ID , DPN.DSGN_DNTN_BIZ_NTC_TTL AS PRJ_NOTICE_SUBJECT
, DPN.DSGN_DNTN_BIZ_NTC_CN AS PRJ_NOTICE_CN
, DPN.RLS_YN AS DISPLAY_YN , DPN.FRST_REG_DT AS FRST_REGIST_PNTTM FROM G_DSGN_DNTN_BIZ_MNG DPM JOIN G_DSGN_DNTN_BIZ_NTC_MNG DPN ON DPM.DSGN_DNTN_BIZ_ID = DPN.DSGN_DNTN_BIZ_ID WHERE 1=1 AND DPM.DSGN_DNTN_BIZ_ID = #{prjId}
AND DPN.RLS_YN = 'Y'
AND DPM.LCLGV_CD = #{locgovCode}
AND DPM.DSGN_DNTN_BIZ_DEPT_ID = #{dsgncntrPartId}
AND DPN.DSGN_DNTN_BIZ_TTL LIKE CONCAT('%', #{searchKeyword}, '%')
ORDER BY DPN.DSGN_DNTN_BIZ_NTC_ID DESC

/* saleson.shop.designateddonation.DesignatedDonationMapper.selectDesignatedDonationNoticeListCnt 공지내역 조회 카운트 */

SELECT
	COUNT(*)
FROM G_DSGN_DNTN_BIZ_MNG DPM
	JOIN G_DSGN_DNTN_BIZ_NTC_MNG DPN ON DPM.DSGN_DNTN_BIZ_ID = DPN.DSGN_DNTN_BIZ_ID
WHERE 1=1
AND DPM.DSGN_DNTN_BIZ_ID = #{prjId}

	AND DPN.RLS_YN = 'Y'


	AND DPM.LCLGV_CD = #{locgovCode}


	AND DPM.DSGN_DNTN_BIZ_DEPT_ID = #{dsgncntrPartId}


	AND DPN.DSGN_DNTN_BIZ_TTL LIKE CONCAT('%', #{searchKeyword}, '%')

/* saleson.shop.designateddonation.DesignatedDonationMapper.selectDesignatedDonationNoticeDetail 공지내역 상세 조회 */
