/** saleson.shop.designateddonation.DesignatedDonationMapper.selectDsgncntrPartMngCnt (지정기부 사업부서 목록 카운트 조회) */
SELECT COUNT(*) FROM G_DSGN_DNTN_BIZ_DEPT_MNG DPM JOIN G_LOCGOV L ON DPM.LCLGV_CD = L.LOCGOV_CODE WHERE 1=1
AND DSGN_DNTN_BIZ_DEPT_NM LIKE CONCAT('%', #{dsgncntrPartName}, '%')
AND DPM.LCLGV_CD = #{locgovCode}
AND DPM.LCLGV_CD IN ( SELECT LOCGOV_CODE FROM G_LOCGOV WHERE UPPER_LOCGOV_CODE = #{upperLocgovCode} )
AND USE_YN = #{useYn}
AND DPM.FRST_REG_DT >= CONCAT(#{searchStDt}, '000000')
AND DPM.FRST_REG_DT <= CONCAT(#{searchEdDt}, '235959')

/** saleson.shop.designateddonation.DesignatedDonationMapper.selectDsgncntrPartMngList (지정기부 사업부서 목록 조회) */
SELECT DPM.DSGN_DNTN_BIZ_DEPT_ID AS DSGNCNTR_PART_ID , DPM.DSGN_DNTN_BIZ_DEPT_NM AS DSGNCNTR_PART_NAME , DPM.LCLGV_CD AS LOCGOV_CODE , L.UPPER_LOCGOV_NM || ' ' || L.LOCGOV_NM AS LOCGOV_NM , DPM.USE_YN , L.UPPER_LOCGOV_CODE , DPM.FRST_REG_DT AS FRST_REGIST_PNTTM FROM G_DSGN_DNTN_BIZ_DEPT_MNG DPM JOIN G_LOCGOV L ON DPM.LCLGV_CD = L.LOCGOV_CODE WHERE 1=1
AND DSGN_DNTN_BIZ_DEPT_NM LIKE CONCAT('%', #{dsgncntrPartName}, '%')
AND DPM.LCLGV_CD = #{locgovCode}
AND DPM.LCLGV_CD IN ( SELECT LOCGOV_CODE FROM G_LOCGOV WHERE UPPER_LOCGOV_CODE = #{upperLocgovCode} )
AND USE_YN = #{useYn}
AND DPM.FRST_REG_DT >= CONCAT(#{searchStDt}, '000000')
AND DPM.FRST_REG_DT <= CONCAT(#{searchEdDt}, '235959')
ORDER BY DPM.DSGN_DNTN_BIZ_DEPT_ID DESC

