/** saleson.shop.designateddonation.DesignatedDonationMapper.insertDsgncntrConfirmLog (지정기부 사업부서-사용자 매핑 삭제) */

INSERT INTO G_DSGN_DNTN_BIZ_APRV_LOG
(
	DSGN_DNTN_BIZ_ID
	, APRV_BFR_DSGN_DNTN_BIZ_STTS_CD
	, APRV_AFTR_DSGN_DNTN_BIZ_STTS_CD
	, FRST_RGTR_ID
)
VALUE
(
	#{prjId}


			, ''


			, (SELECT DSGN_DNTN_BIZ_STTS_CD FROM G_DSGN_DNTN_BIZ_MNG WHERE DSGN_DNTN_BIZ_ID = #{prjId})


	, '2'
	, #{lastUpdusrId}
)

mapper.select:
/** saleson.shop.designateddonation.DesignatedDonationMapper.selectDsgncntrConfirmLogCnt (지정기부 사업부서-사용자 매핑 삭제) */

	SELECT
		COUNT(*)
	FROM G_DSGN_DNTN_BIZ_APRV_LOG DCL
		JOIN G_DSGN_DNTN_BIZ_MNG DPM ON DCL.DSGN_DNTN_BIZ_ID = DPM.DSGN_DNTN_BIZ_ID

		JOIN G_DSGN_DNTN_BIZ_DEPT_MNGR_MPNG DPUM ON DPM.DSGN_DNTN_BIZ_DEPT_ID = DPUM.DSGN_DNTN_BIZ_DEPT_ID
											AND DPUM.USER_ID = #{userId}


		JOIN OP_MANAGER M ON DPM.LCLGV_CD = M.LOCGOV_CODE
							AND M.USER_ID = #{userId}

	WHERE 1=1
	AND DCL.DSGN_DNTN_BIZ_ID = #{prjId}

/** saleson.shop.designateddonation.DesignatedDonationMapper.selectDsgncntrConfirmLog (지정기부 사업부서-사용자 매핑 삭제) */
SELECT LOG_NO , DSGNCNTR_CONFIRM_ID , PRJ_ID , BF_STATUS , TB_STATUS , REGISTER_ID , IFNULL(USER_NAME, '사용자 정보 없음') AS REGISTER_NAME , REGIST_PNTTM , PRJ_SUBJECT FROM (
SELECT ROWNUM AS LOG_NO , DCL.DSGN_DNTN_BIZ_APRV_ID AS DSGNCNTR_CONFIRM_ID , DCL.DSGN_DNTN_BIZ_ID AS PRJ_ID , DCL.APRV_BFR_DSGN_DNTN_BIZ_STTS_CD AS BF_STATUS , DCL.APRV_AFTR_DSGN_DNTN_BIZ_STTS_CD AS TB_STATUS , DCL.FRST_RGTR_ID AS REGISTER_ID , M2.USER_NAME , DCL.FRST_REG_DT AS REGIST_PNTTM , DPM.DSGN_DNTN_BIZ_TTL AS PRJ_SUBJECT FROM G_DSGN_DNTN_BIZ_APRV_LOG DCL JOIN G_DSGN_DNTN_BIZ_MNG DPM ON DCL.DSGN_DNTN_BIZ_ID = DPM.DSGN_DNTN_BIZ_ID
JOIN G_DSGN_DNTN_BIZ_DEPT_MNGR_MPNG DPUM ON DPM.DSGN_DNTN_BIZ_DEPT_ID = DPUM.DSGN_DNTN_BIZ_DEPT_ID AND DPUM.USER_ID = #{userId}
JOIN OP_MANAGER M ON DPM.LCLGV_CD = M.LOCGOV_CODE AND M.USER_ID = #{userId}
LEFT JOIN OP_MANAGER M2 ON DCL.FRST_RGTR_ID = M2.USER_ID WHERE 1=1 AND DCL.DSGN_DNTN_BIZ_ID = #{prjId} ORDER BY DCL.DSGN_DNTN_BIZ_APRV_ID DESC
)

mapper.update:
/** saleson.shop.designateddonation.DesignatedDonationMapper.updateManagerRequestPartName (관리자 신청 부서명 수정) */
UPDATE
		G_MNGR_REQST MR LEFT JOIN G_DSGN_DNTN_BIZ_DEPT_MNG DM ON MR.LOCGOV_CODE = DM.LCLGV_CD
																AND DM.DSGN_DNTN_BIZ_DEPT_ID = #{dsgncntrPartId}
SET
		LAST_UPDUSR_ID = #{lastUpdusrId},
		LAST_UPDT_PNTTM = 

			, CONFM_STTUS_CODE = #{confmSttusCode}


			, REJECT_RESN = #{rejectResn}

		, PSITN_DEPT_NM = DM.DSGN_DNTN_BIZ_DEPT_NM
WHERE
		USER_ID = #{userId}
	AND	REQST_SN = #{reqstSn}
